(function(){'use strict';
const app=document.getElementById('app'),dialog=document.getElementById('archive-dialog'),view=document.body.dataset.view;
const names={draft:'待完善',pending:'待审核',approved:'待归档',archived:'已归档',rejected:'已驳回',unknown:'未评估',low:'低风险',medium:'中风险',high:'高风险',critical:'极高风险'};
const stages={uploaded:'原件已保存 · 等待识别',ocr_complete:'OCR完成',extracted:'候选结果已保存',standardized:'已匹配字典',pending_review:'待医生审核',published:'正式归档',failed:'识别失败'};
const auditActions={
 report_removed:'删除报告',misassigned_report_removed:'删除误传报告',misassigned_report_unlinked:'解除报告关联',
 report_uploaded:'上传报告',ocr_candidate_received:'接收识别结果',ocr_requested:'发起报告识别',
 ocr_task_cancelled:'停止报告识别',ocr_task_retried:'重试报告识别',manual_candidate_saved:'补录报告结果',
 report_submitted:'提交人工审核',report_approve:'报告审核通过',report_return:'退回补充材料',report_returned:'退回补充材料',
 report_reject:'报告审核未通过',report_archive:'报告归档',revision_created:'创建修订版本',
 wechat_employee_bound:'微信绑定',wechat_employee_unbound:'解除微信绑定',
 binding_code_issued:'生成身份验证码',binding_code_revoked:'撤销身份验证码',
 agent_action_confirmed:'确认智能体操作',profile_saved:'保存职工资料',profile_deleted:'删除职工档案',legacy_roster_imported:'同步原系统职工资料',
 profile_correction_requested:'提交资料更正申请',profile_correction_approved:'资料更正审核通过',
 profile_correction_rejected:'资料更正审核未通过',records_exported:'导出档案'
};
const auditLabel=action=>auditActions[action]||'其他操作记录';
let ctx,stats,list={items:[],total:0,page:1,limit:10},filters={},person=null,chosen=new Set(),charts=[],generation=0,editor=null;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{let r=Math.random()*16|0;return(c==='x'?r:r&3|8).toString(16)});
function toast(text){let t=document.getElementById('toast');t.textContent=text;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),5000);}
async function api(path,method='GET',body,headers={}){const init={method,credentials:'same-origin',headers:{...headers}};if(method!=='GET')init.headers['X-CSRF-Token']=ctx?.csrfToken||'';if(body instanceof FormData)init.body=body;else if(body!==undefined){init.body=JSON.stringify(body);init.headers['Content-Type']='application/json';}const r=await fetch('/ehr/api'+path,init);let j;try{j=await r.json()}catch(e){throw Error('服务没有返回有效JSON，请检查登录状态')}if(!r.ok||j.code!==0)throw Error(j.msg||'操作失败（'+r.status+'）');return j.data;}
const button=(label,action,extra='',cls='')=>`<button type="button" class="btn ${cls}" data-do="${action}" ${extra}>${label}</button>`;
const archiveFilterKeys=['search','name','code','phone','org','team','job','status','risk','from','to'];
const isListView=['management','review','archive'].includes(view);
function readListLocation(){
 const query=new URLSearchParams(location.search);filters={};
 for(const key of archiveFilterKeys)if(query.get(key))filters[key]=query.get(key);
 if(view==='review'&&!query.has('status'))filters.status='pending';
 const page=query.get('page')||'1';list.page=/^[1-9]\d{0,5}$/.test(page)?Math.min(100000,Number(page)):1;
}
function writeListLocation(){
 if(!isListView)return;
 const url=new URL(location.href);for(const key of [...archiveFilterKeys,'page'])url.searchParams.delete(key);
 for(const key of archiveFilterKeys)if(filters[key])url.searchParams.set(key,filters[key]);
 // Preserve an explicit empty review status: it means all statuses rather than the default pending tab.
 if(view==='review'&&!filters.status)url.searchParams.set('status','');
 url.searchParams.set('page',String(list.page));window.history.replaceState(window.history.state,'',url);
}
function listScrollKey(){return 'ehr-list-position:'+JSON.stringify([ctx?.user,ctx?.scope,ctx?.dataMode,view]);}
function saveListPosition(){
 if(!isListView||!ctx)return;
 try{sessionStorage.setItem(listScrollKey(),JSON.stringify({url:location.pathname+location.search,y:window.scrollY}));}catch(ignore){}
}
function restoreListPosition(){
 if(!isListView)return;
 try{const saved=JSON.parse(sessionStorage.getItem(listScrollKey())||'null');
  if(saved?.url===location.pathname+location.search&&Number.isFinite(saved.y)&&saved.y>=0)
   requestAnimationFrame(()=>requestAnimationFrame(()=>window.scrollTo({top:saved.y,behavior:'instant'})));
 }catch(ignore){}
}
function detailLocation(id){
 const target=new URL('detail.html',location.href);target.searchParams.set('id',id);
 if(isListView)target.searchParams.set('returnTo',location.pathname+location.search);
 return target.pathname+target.search;
}
function returnListLocation(){
 const raw=new URLSearchParams(location.search).get('returnTo');
 if(raw)try{const url=new URL(raw,location.href);
  if(url.origin===location.origin&&['/assets/health-archive/management.html','/assets/health-archive/review.html','/assets/health-archive/index.html','/assets/report-center/employees.html','/assets/report-center/occupational.html'].includes(url.pathname))
   return url.pathname+url.search;
 }catch(ignore){}
 return 'management.html';
}
async function changeListPage(page){
 const pages=Math.max(1,Math.ceil(list.total/list.limit));
 if(!Number.isInteger(page)||page<1||page>pages)throw Error('请输入 1 至 '+pages+' 之间的整数页码');
 if(page===list.page)return;
 const previous=list.page;const footer=document.querySelector('.archive-pager');
 if(footer){footer.setAttribute('aria-busy','true');footer.querySelectorAll('button,input').forEach(el=>el.disabled=true);}
 list.page=page;
 try{await refresh();}catch(error){list.page=previous;throw error;}
 finally{if(footer){footer.removeAttribute('aria-busy');footer.querySelectorAll('button,input').forEach(el=>el.disabled=false);}}
}
document.addEventListener('submit',e=>{
 if(!e.target.matches('[data-page-jump-form]'))return;e.preventDefault();
 const input=e.target.elements.page,raw=input.value.trim(),pages=Math.max(1,Math.ceil(list.total/list.limit));
 if(!/^[1-9]\d*$/.test(raw)||!Number.isSafeInteger(Number(raw))||Number(raw)>pages){
  input.setCustomValidity('请输入 1 至 '+pages+' 之间的整数页码');input.reportValidity();return;
 }
 input.setCustomValidity('');guard(()=>changeListPage(Number(raw)));
});
document.addEventListener('input',e=>{if(e.target.matches('[data-page-jump]'))e.target.setCustomValidity('');});
document.addEventListener('click',e=>{if(isListView&&e.target.closest('a[href*="detail.html"]'))saveListPosition();});
window.addEventListener('pagehide',saveListPosition);
window.addEventListener('popstate',()=>{if(isListView){readListLocation();guard(async()=>{await refresh();restoreListPosition();});}});
let ocrTimer;
function modal(title,html){clearTimeout(ocrTimer);delete dialog.dataset.ocrJob;document.getElementById('dialog-content').innerHTML=`<div class="dialog-head"><strong>${esc(title)}</strong><button data-do="close" aria-label="关闭">×</button></div><div class="dialog-body">${html}<p id="form-error" class="form-error" role="alert"></p></div>`;if(!dialog.open)dialog.showModal();}
function formHandler(id,fn){document.getElementById(id).onsubmit=async e=>{e.preventDefault();const b=e.submitter;if(b)b.disabled=true;try{await fn(e.target)}catch(err){document.getElementById('form-error').textContent=err.message}finally{if(b)b.disabled=false}};}
function header(title){return `<div class="page-nav"><span><a href="index.html">健康档案</a> / ${esc(title)}</span><span><a href="index.html">智能档案</a><a href="statistics.html">统计分析</a><a href="management.html">信息管理</a><a href="review.html">审核归档</a><button type="button" class="btn soft" data-do="refresh">刷新数据</button><i class="demo">${ctx.dataMode==='real'?'数据库实时数据':'测试数据 · synthetic隔离'}</i></span></div>`;}
function hero(title){return `<section class="hero manage-hero"><div class="hero-copy"><div class="eyebrow">KUANGAN ZHIKANG · HEALTH RECORDS</div><h1>${title}</h1><p>以原始体检报告为基础，连接授权档案、识别结果、医生审核与正式归档。</p><div class="actions"><a class="btn" href="management.html">档案信息管理</a><a class="btn blue" href="statistics.html">查看企业统计</a></div></div><svg class="hero-art" viewBox="0 0 460 180" aria-hidden="true"><path d="m0 180 80-95 60 47 75-105 90 110 75-53 80 65v31" fill="#a0d7e9"/><path d="m0 180 120-50 160 20 180-65v95" fill="#8acdcf"/><path d="m170 180 45-140 45 140M190 120h50M180 150h70M202 80h28M215 40V16h25v30h-36M250 95h95v15l-90 20M270 126v54M330 110v70" stroke="#4899ba" stroke-width="3" fill="none"/></svg></section>`;}
function kpis(){return `<div class="kpis manage-kpis">${[['total','在档人数'],['archived','已归档档案'],['draft','待完善档案'],['pending','待审核档案'],['high','高风险档案']].map(([k,n])=>`<button class="kpi" data-filter="${k}"><span><label>${n}</label><b>${Number(stats[k]||0).toLocaleString()}<small> 人</small></b><small>${k==='archived'?'当前状态已归档的职工':'同单位、同数据模式口径'}</small></span></button>`).join('')}</div>`;}
const pill=(v)=>`<span class="badge ${esc(v)}">${names[v]||esc(v)}</span>`;
function pager(){const pages=Math.max(1,Math.ceil(list.total/list.limit));return `<div class="table-footer archive-pager"><span role="status" aria-live="polite">共 ${list.total} 条 · 第 ${list.page} / ${pages} 页</span><div class="archive-page-controls">${button('上一页','page',`data-page="${list.page-1}" ${list.page<=1?'disabled':''}`,'soft')}${button('下一页','page',`data-page="${list.page+1}" ${list.page>=pages?'disabled':''}`,'soft')}<form class="archive-page-jump" data-page-jump-form novalidate><label for="archive-jump-page">跳至</label><input id="archive-jump-page" data-page-jump name="page" type="text" inputmode="numeric" pattern="[0-9]*" maxlength="6" value="${list.page}" aria-label="跳转页码" ${!list.total?'disabled':''}><span>页</span><button type="submit" class="btn soft" ${!list.total?'disabled':''}>跳转</button></form></div></div>`;}

function filterForm(){return `<div class="filter-help">按身份、职业、状态和建档时间查询</div><form id="filters" class="live-filters"><input name="search" placeholder="搜索姓名 / 工号 / 班组" value="${esc(filters.search||'')}"><input name="phone" placeholder="联系电话" value="${esc(filters.phone||'')}">${[ ["code","工号"],["org","单位"],["team","班组"],["job","岗位"] ].map(([k,n])=>`<input name="${k}" placeholder="${n}" value="${esc(filters[k]||'')}">`).join('')}<label>建档起<input name="from" type="date" value="${esc(filters.from||'')}"></label><label>建档止<input name="to" type="date" value="${esc(filters.to||'')}"></label><select name="status"><option value="">全部状态</option>${['draft','pending','approved','archived','rejected'].map(k=>`<option value="${k}" ${filters.status===k?'selected':''}>${names[k]}</option>`).join('')}</select><select name="risk"><option value="">全部风险</option>${['unknown','low','medium','high','critical'].map(k=>`<option value="${k}" ${filters.risk===k?'selected':''}>${names[k]}</option>`).join('')}</select><button class="btn">查询</button>${button('重置','reset','','soft')}</form>`;}
function rows(){return `<div class="table-scroll"><table class="archive-table"><thead><tr><th><input type="checkbox" id="all-rows" aria-label="选择本页"></th><th>职工信息</th><th>单位 / 班组 / 岗位</th><th>建档时间</th><th>完整度</th><th>风险</th><th>业务状态</th><th>操作</th></tr></thead><tbody>${list.items.map(p=>`<tr><td><input type="checkbox" data-check="${p.id}" ${chosen.has(p.id)?'checked':''} aria-label="选择${esc(p.name)}"></td><td><div class="worker-cell"><span class="worker-avatar">${esc(p.name.slice(0,1))}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.code)} · ${esc(p.sex)} · ${p.age==null?'年龄未填':p.age+'岁'}</small></span></div></td><td>${esc(p.org)}<small>${esc(p.team||'未填班组')} / ${esc(p.job||'未填岗位')}</small></td><td>${esc(p.created)}</td><td><div class="progress-cell"><div class="track"><i style="--w:${Number(p.complete)}%"></i></div>${p.complete}%</div></td><td>${pill(p.risk)}</td><td>${pill(p.status)}</td><td><div class="row-actions"><a href="${esc(detailLocation(p.id))}">查看档案</a><button data-do="edit" data-id="${p.id}">编辑</button>${ctx.canReview?`<button data-do="binding-code" data-id="${p.id}">微信身份绑定</button><button data-do="corrections" data-id="${p.id}">更正记录</button>`:''}<button class="danger" data-do="delete" data-id="${p.id}">删除</button></div></td></tr>`).join('')||'<tr><td colspan="8" class="empty-table">当前没有匹配的真实档案。可新增档案或由小程序上传后查看。</td></tr>'}</tbody></table></div>`;}
function sidebar(){return `<aside class="manage-side"><section class="panel"><div class="panel-title">档案业务助手</div><div class="assistant-feature"><span><strong>原件与结果分开保存</strong><small>PDF / PNG / JPEG，单文件不超过20 MB。</small></span></div><div class="assistant-feature"><span><strong>审核前保留候选状态</strong><small>OCR结果通过API接收，结果不直接成为正式档案。</small></span></div><div class="assistant-feature"><span><strong>退回修改建立新版本</strong><small>已审核数据不可覆盖，历史报告和证据保留。</small></span></div></section><section class="panel insight"><h3>待处理事项</h3><p>待审核 ${stats.pending} 人，待归档 ${stats.approved} 人。</p><a href="review.html">进入审核与归档 →</a><p>未评估 ${stats.unknown} 人；医学结论与平台风险等级分别管理。</p></section></aside>`;}
async function refresh(){const g=++generation;charts.forEach(c=>c.dispose());charts=[];stats=await api('/statistics');if(view==='statistics'){drawStatistics();return}if(view==='detail'){person=await api('/records/'+encodeURIComponent(new URLSearchParams(location.search).get('id')||''));if(g===generation)drawDetail();return}
 list=await api('/records?'+new URLSearchParams({...filters,page:list.page,limit:view==='archive'?20:10}));if(g!==generation)return;
 const lastPage=Math.max(1,Math.ceil(list.total/list.limit));
 if(list.page>lastPage){list.page=lastPage;list=await api('/records?'+new URLSearchParams({...filters,page:list.page,limit:view==='archive'?20:10}));if(g!==generation)return;}
 writeListLocation();if(view==='archive'){if(!person||!list.items.some(p=>p.id===person.id))person=list.items[0]?await api('/records/'+list.items[0].id):null;else person=await api('/records/'+person.id);drawArchive()}else drawManagement();}
function drawManagement(){app.innerHTML=`<main class="shell">${header(view==='review'?'档案审核与归档':'档案信息管理')}${hero(view==='review'?'档案审核与归档':'档案信息管理')}${kpis()}<div class="panel manage-toolbar"><div class="actions">${button('＋ 新增档案','new')}${button('上传体检报告','upload','','blue')}${button('识别任务','ocr-tasks','','soft')}${button('拍照上传','camera','','soft')}${button('小程序同步','sync','','light')}${button('资料更正申请','corrections','','soft')}${button('批量导入','import','','soft')}<a class="btn soft" href="/ehr/api/records/export?${new URLSearchParams(filters)}">导出当前查询</a>${ctx.canReview?button('批量审核','batch-approve','','soft')+button('批量归档','batch-archive','','soft'):''}</div></div><div class="manage-layout"><section class="panel management-panel">${view==='review'?'<nav class="review-tabs">'+['pending','approved','archived','draft','rejected','all'].map(k=>`<button data-status="${k}" class="${filters.status===k?'active':''}">${names[k]||'全部'}</button>`).join('')+'</nav>':''}${filterForm()}<div class="batch-bar">已选择 ${chosen.size} 项 · 状态与风险分别管理</div>${rows()}${pager()}</section>${sidebar()}</div></main>`;wireList();}
function wireList(){document.getElementById('filters').onsubmit=e=>{e.preventDefault();filters=Object.fromEntries(new FormData(e.target));list.page=1;chosen.clear();guard(refresh)};const all=document.getElementById('all-rows');if(all)all.onchange=()=>{list.items.forEach(p=>all.checked?chosen.add(p.id):chosen.delete(p.id));drawManagement()};}
function info(p){return `<div class="info-grid">${[['姓名',p.name],['工号',p.code],['性别',p.sex],['出生日期',p.birth||'未填写'],['手机号',p.phone||'未填写'],['单位',p.org],['班组',p.team||'未填写'],['岗位',p.job||'未填写'],['关联小程序用户',p.legacyUserCode||'未关联']].map(([n,v])=>`<div><label>${n}</label>${esc(v)}</div>`).join('')}</div>`;}
function reportCard(r){let editable=!['confirmed','rejected'].includes(r.reviewStatus)&&!r.reviews.length;return `<article class="report-manage"><header><strong>${esc(r.files[0]?.name||'体检报告')} · V${r.revision}</strong><span class="badge">${r.published?'正式归档':r.stage==='pending_review'?'待医生审核':r.reviewStatus==='confirmed'?'医生已确认 · 待归档':r.ocrTask?ocrStateLabel(r.ocrTask):stages[r.stage]||r.stage}</span>${r.canRemove?`<button type="button" class="report-remove" data-do="remove-report" data-report="${r.id}" data-rev="${r.revision}" title="移除这份报告" aria-label="移除这份报告">&times;</button>`:''}</header>${r.ocrTask?`<div class="ocr-inline"><div class="ocr-track"><i style="width:${Number(r.ocrTask.percent||0)}%"></i></div>${button("查看识别进度","ocr-progress",`data-job="${r.ocrTask.jobId}"`,"soft")}</div>`:""}${!r.published&&r.reviewStatus!=="confirmed"&&r.qualityChecks?.some(q=>q.identityStatus!=="matched")?`<p class="ocr-warning">报告身份信息缺失或与所选职工不一致，请对照原件核查。</p>`:""}<p>体检日期：${esc(r.examDate||(draftExamDate(r)?draftExamDate(r)+'（候选，待核对）':'待核定'))} · 机构：${esc(draftInstitution(r)||'待填写')}</p><div class="actions">${r.files.map(f=>`<a class="btn soft" href="/ehr/api/files/${f.id}">下载原件 · ${f.pageCount}页</a>`).join('')}${button('报告详情 / 历史','history',`data-report="${r.id}" data-rev="${r.revision}"`,'soft')}${editable?button('重新发起识别','ocr',`data-report="${r.id}" data-rev="${r.revision}"`,'soft')+button('补录 / 核对结果','candidate',`data-report="${r.id}" data-rev="${r.revision}"`,'light'):button('建立修订版本','revise',`data-report="${r.id}" data-rev="${r.revision}"`,'soft')}</div><div class="mini-metrics">${r.items.slice(0,12).map(i=>`<span>${esc(i.name)}：${esc(i.value??'未识别')} ${esc(i.unit||'')}</span>`).join('')||'<p>原件已入库，尚无结构化检查结果。</p>'}</div>${r.conclusions.length?'<div class="note-box"><strong>报告原文结论</strong><p>'+esc(formalConclusions(r).map(c=>c.text||'').join('\n'))+'</p></div>':''}<div class="actions">${editable?button('提交人工审核','action',`data-action="submit" data-report="${r.id}" data-rev="${r.revision}"`):''}${r.stage==='pending_review'&&ctx.canReview?button('医生审核通过','action',`data-action="approve" data-report="${r.id}" data-rev="${r.revision}"`)+button('退回补充','action',`data-action="return" data-report="${r.id}" data-rev="${r.revision}"`,'soft')+button('驳回','action',`data-action="reject" data-report="${r.id}" data-rev="${r.revision}"`,'soft'):''}${r.reviewStatus==='confirmed'&&!r.published&&ctx.canReview?button('正式归档','action',`data-action="archive" data-report="${r.id}" data-rev="${r.revision}"`):''}</div></article>`;}
function drawDetail(){app.innerHTML=`<main class="shell">${header('档案详情管理')}<div class="detail-head"><span class="worker-avatar">${esc(person.name[0])}</span><div><h2>${esc(person.name)} ${pill(person.status)} ${pill(person.risk)}</h2><p>${esc(person.code)} · ${esc(person.org)} · ${person.complete}%完整度</p></div><div class="actions">${button('编辑授权资料','edit',`data-id="${person.id}"`)}${button('上传报告','upload','','blue')}<a class="btn soft" data-return-list href="${esc(returnListLocation())}">返回列表</a></div></div><div class="detail-layout"><section class="panel detail-content"><h3>基本身份与职业信息</h3>${info(person)}<h3>职业危害与接触史</h3><div class="note-box">${esc(person.exposure||'尚未填写')}</div><h3>完整性检查</h3><div class="note-box">${person.missing.length?'待完善：'+esc(person.missing.join('、')):'当前必需资料已齐备，正式归档仍须医生审核。'}</div><h3 id="reports">历次报告、原件与检查结果</h3>${person.reports.map(reportCard).join('')||'<div class="empty">暂无报告，请上传原件。</div>'}</section><aside class="panel"><div class="panel-title">修改、审核与归档记录</div><div class="logs">${person.logs.map(l=>`<div><time>${esc(l.time)} · ${esc(l.actor)}</time><strong>${esc(auditLabel(l.action))}</strong><small>${esc(l.note)}</small></div>`).join('')}</div></aside></div></main>`;}
function drawArchive(){app.innerHTML=`<main class="shell">${header('智能档案页')}${hero('健康档案中心 · 智能健康档案')}${kpis()}<div class="workspace"><section class="panel people-panel"><div class="panel-title">职工档案列表 · ${list.total}人</div><form id="people-filter" class="live-filters"><input name="search" placeholder="姓名 / 工号 / 班组" value="${esc(filters.search||'')}"><button class="btn">搜索</button></form><div class="person-list">${list.items.map(p=>`<button class="person ${person?.id===p.id?'active':''}" data-person="${p.id}"><span class="worker-avatar">${esc(p.name[0])}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.code)} · ${esc(p.team||'未填班组')}</small></span>${pill(p.risk)}</button>`).join('')||'<div class="empty">暂无档案</div>'}</div>${pager()}</section><section class="panel profile-panel">${person?`<div class="detail-head"><span class="worker-avatar">${esc(person.name[0])}</span><div><h2>${esc(person.name)} ${pill(person.risk)}</h2><p>${esc(person.code)} · ${esc(person.team)} / ${esc(person.job)}</p></div><b>${person.complete}%</b></div><nav class="content-tabs"><strong>个人健康档案</strong><a href="${esc(detailLocation(person.id))}">详情与报告管理 →</a></nav><div class="live-padding">${info(person)}<h3>已发布体检报告</h3>${(person.publishedReports||[]).filter(r=>r.published).map(reportCard).join('')||'<div class="empty">尚无正式归档报告。上传材料可在“信息管理”中补录和送审。</div>'}<h3>职业接触史</h3><div class="note-box">${esc(person.exposure||'暂无授权填报信息')}</div></div>`:'<div class="empty"><h2>建立第一份健康档案</h2><p>当前单位尚未录入职工档案。</p><a class="btn" href="management.html">进入信息管理新增档案</a></div>'}</section>${sidebar()}</div></main>`;document.getElementById('people-filter').onsubmit=e=>{e.preventDefault();filters={search:e.target.search.value};list.page=1;person=null;guard(refresh)};}
function chart(id,option){if(!window.echarts)return;let c=echarts.init(document.getElementById(id),null,{renderer:'svg'});c.setOption(option);charts.push(c);}
function drawStatistics(){app.innerHTML=`<main class="shell">${header('档案统计分析')}${hero('健康档案统计分析')}${kpis()}<div class="live-stat-grid"><section class="panel"><h3>档案增长趋势</h3><div class="live-chart" id="growth"></div></section><section class="panel"><h3>业务状态分布</h3><div class="live-chart" id="statuses"></div></section><section class="panel"><h3>风险等级分布</h3><div class="live-chart" id="risks"></div></section><section class="panel"><h3>报告上传渠道（上传次数）</h3><div class="live-chart" id="sources"></div></section><section class="panel"><h3>年龄结构（在档人数）</h3><div class="live-chart" id="ages"></div></section><section class="panel"><h3 id="archive-teams-title">班组在档人数</h3><div class="live-team-scroll" role="region" aria-labelledby="archive-teams-title" tabindex="0">${Object.entries(stats.teams).map(([k,v])=>`<div class="rank-row"><span>${esc(k)}</span><div class="track"><i style="--w:${stats.total?v/stats.total*100:0}%"></i></div><strong>${v}</strong></div>`).join('')||'<div class="empty">暂无在档人员</div>'}<p class="notice">职业暴露人数来自授权资料填报，风险等级仅统计独立评估结果。</p></div></section></div></main>`;let pie=(id,entries)=>chart(id,{color:id==='risks'?['#99afbc','#19c89c','#4eabf7','#ffc463','#ff6e82']:['#19c89c','#4eabf7','#ffc463','#ff6e82','#9b83ee','#99afbc'],tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',stillShowZeroSum:false,radius:['44%','70%'],label:{show:false},data:entries.map(([name,value])=>({name,value}))}]});chart('growth',{tooltip:{trigger:'axis'},grid:{left:45,right:20,bottom:45},xAxis:{type:'category',data:stats.growth.map(x=>x.month)},yAxis:{type:'value',min:0,minInterval:1},series:[{type:'line',smooth:true,data:stats.growth.map(x=>x.count),lineStyle:{color:'#00b896'},areaStyle:{color:'#b5f1df'},itemStyle:{color:'#00b896'}}]});pie('statuses',['draft','pending','approved','archived','rejected'].map(k=>[names[k],stats[k]]));pie('risks',['unknown','low','medium','high','critical'].map(k=>[names[k],stats[k]]));const channels={miniapp:'小程序上传',phone_photo:'拍照上传',backend_file:'后台文件',batch_import:'批量导入',legacy_import:'历史导入'};pie('sources',stats.sources.map(x=>[channels[x.channel]||x.channel,x.count]));chart('ages',{tooltip:{trigger:'axis'},grid:{left:40,right:15,bottom:40},xAxis:{type:'category',data:Object.keys(stats.ages)},yAxis:{type:'value',minInterval:1},series:[{type:'bar',data:Object.values(stats.ages),itemStyle:{color:'#20c79c'}}]});}
function field(k,label,v='',type='text',required=false){return `<label>${label}<input name="${k}" type="${type}" value="${esc(v??'')}" ${required?'required':''} maxlength="${k==='org'?255:100}"></label>`;}
const correctionFields={organization:'单位名称',team:'班组',position:'岗位 / 工种',phone:'联系电话',gender:'性别',birthDate:'出生日期'};
const correctionStatuses={pending:'待审核',approved:'已通过',rejected:'已驳回'};
async function corrections(record='',status='pending',page=1){
 const q=new URLSearchParams({status,page,limit:10});if(record)q.set('recordId',record);const data=await api('/correction-requests?'+q);
 const tabs=['pending','approved','rejected','all'].map(k=>button(correctionStatuses[k]||'全部','corrections',`data-id="${esc(record)}" data-status-correction="${k}"`,status===k?'':'soft')).join('');
 modal('职工资料更正申请',`<p>职工申请与正式名册分开；通过审核才更新。姓名、工号不符请人工核查。待审核期间不能绑定。</p><div class="actions">${tabs}</div>${data.items.map(r=>`<section class="note-box"><h3>${esc(r.before.name)} · 工号 ${esc(r.before.employeeNo)} <small>${correctionStatuses[r.status]}</small></h3><p>提交：${esc(r.createdAt)} · 原因：${esc(r.reason)}</p><div class="table-scroll"><table><thead><tr><th>字段</th><th>申请时原资料</th><th>申请更正为</th></tr></thead><tbody>${Object.entries(r.changes).map(([k,v])=>`<tr><td>${correctionFields[k]||esc(k)}</td><td>${esc(r.before[k==='phone'?'phoneMasked':k]||'未填写')}</td><td>${esc(v||'清空')}</td></tr>`).join('')}</tbody></table></div>${r.status==='pending'&&ctx.canReview?`<form data-correction-form="${r.id}"><label>人工核对说明<textarea name="note" required maxlength="600" placeholder="核实本人、班组及岗位资料后填写审核依据；资料已变动时请驳回重新申请"></textarea></label><div class="actions"><button class="btn" name="decision" value="approve">审核通过并更新资料</button><button class="btn soft" name="decision" value="reject">驳回申请</button></div></form>`:`<p>审核时间：${esc(r.reviewedAt||'未处理')} · ${esc(r.reviewNote||'等待医生核对')}</p>`}</section>`).join('')||'<div class="empty">没有匹配的更正申请</div>'}<div class="actions"><span>共 ${data.total} 条 · 第 ${page} 页</span>${button('上一页','corrections',`data-id="${esc(record)}" data-status-correction="${status}" data-correction-page="${page-1}" ${page<=1?'disabled':''}`,'soft')}${button('下一页','corrections',`data-id="${esc(record)}" data-status-correction="${status}" data-correction-page="${page+1}" ${page*10>=data.total?'disabled':''}`,'soft')}</div>`);
 document.querySelectorAll('[data-correction-form]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{const r=data.items.find(r=>r.id===f.dataset.correctionForm);await api('/correction-requests/'+r.id+'/review','POST',{decision:btn.value,note:f.elements.note.value,rowVersion:r.rowVersion,requestKey:uid()});await refresh();await corrections(record,status,page);toast('更正申请已处理，职工需重新核对并确认绑定')}catch(err){document.getElementById('form-error').textContent=err.message}finally{btn.disabled=false}});
}
async function bindingSettings(id){const state=await api('/records/'+id+'/binding');const c=state.lastCode;modal('职工微信身份绑定',`<p>当前状态：${state.bound?'已绑定微信用户':'未绑定'}。${c?'最近验证码：'+esc(c.status)+'；有效期至 '+esc(c.expiresAt):'尚未签发验证码。'}</p>${state.bound?'<form id="unbind-form"><p>解除前请核对本人身份。解除后，该微信用户的会话会失效。</p><textarea name="reason" required maxlength="600" placeholder="填写人工核对和解除原因"></textarea><button class="btn">确认解除绑定</button></form>':'<form id="binding-code-form"><p>每人独立随机验证码，确认绑定时一次性使用。重发会撤销旧码；明文仅本次显示。</p><label>有效期<select name="expiresIn"><option value="86400">24小时</option><option value="604800">7天</option><option value="3600">1小时</option></select></label><button class="btn">生成个人专属验证码</button></form>'+button('撤销当前验证码','revoke-binding-code',`data-id="${id}"`,'soft')}`);if(state.bound)formHandler('unbind-form',async f=>{await api('/records/'+id+'/binding/revoke','POST',{reason:f.reason.value});dialog.close();toast('绑定已解除，原微信会话已失效')});else formHandler('binding-code-form',async f=>{const issued=await api('/records/'+id+'/binding-code','POST',{requestKey:uid(),expiresIn:Number(f.expiresIn.value)});modal('个人专属验证码 · 仅本次显示',`<p>${esc(issued.name)} · 工号 ${esc(issued.employeeNo)}</p><input class="input" readonly value="${esc(issued.verificationCode)}" aria-label="个人专属验证码" onclick="this.select()"><p>有效期至 ${esc(issued.expiresAt)}。请将此验证码私下交给对应职工。关闭后不能查询原文，需要时重新生成。</p>`)});}
async function edit(id){const p=id?await api('/records/'+id):{sex:'未填写'};modal(id?'编辑授权档案':'新增职工健康档案',`<form id="edit-form"><p>此处维护授权身份与职业资料，报告中的原始姓名、检查值和医生结论单独保存。</p><div class="form-fields">${field('name','姓名 *',p.name,'text',true)}${field('code','工号 *',p.code,'text',true)}${field('org','单位名称 *',p.org,'text',true)}${field('team','班组',p.team)}${field('job','岗位 / 工种',p.job)}${field('phone','联系电话',p.phone,'tel')}${field('birth','出生日期',p.birth,'date')}<label>性别<select name="sex">${['男','女','未填写'].map(k=>`<option ${p.sex===k?'selected':''}>${k}</option>`).join('')}</select></label>${field('legacyUserCode','小程序用户编码（选填，须属于当前单位）',p.legacyUserCode)}<label class="wide">职业危害与接触史<textarea name="exposure" rows="3" maxlength="4000">${esc(p.exposure||'')}</textarea></label></div><button class="btn">保存档案</button></form>`);formHandler('edit-form',async f=>{const b=Object.fromEntries(new FormData(f));b.rowVersion=p.rowVersion;await api('/records'+(id?'/'+id:''),id?'PUT':'POST',b);dialog.close();await refresh();toast('档案已保存到数据库')});}
const ocrStateNames={queued:'等待识别任务处理',running:'正在识别',retry_wait:'等待重试',succeeded:'识别完成 · 待人工核对',failed:'识别失败',cancelled:'识别已停止'};
const ocrStageNames={queued:'已领取，准备处理',pdf_parse:'PDF解析 / 文字提取',ocr:'图片文字识别',field_extraction:'标准档案字段提取',item_matching:'医学检查项目匹配',validation:'结果整理与校验',finished:'结果已保存'};
function ocrStateLabel(t){return (ocrStateNames[t.state]||t.state)+(t.state==='running'?' · '+Number(t.percent||0)+'%':'');}
async function ocrTaskList(state='active',page=1){const data=await api('/ocr/tasks?'+new URLSearchParams({state,page,limit:10}));modal('体检报告识别任务',`<p>上传原件后自动排队，最多同时识别 ${Number(ctx.recognition?.concurrentReports||1)} 份报告；完成后需人工核对、审核并归档。</p><div class="actions">${['active','failed','succeeded','all'].map(k=>button({active:'处理中',failed:'失败任务',succeeded:'识别完成',all:'全部记录'}[k],'ocr-tasks',`data-ocr-state="${k}"`,state===k?'':'soft')).join('')}</div>${data.items.map(t=>`<section class="ocr-task-row"><div><strong>${esc(t.employeeName)} · ${esc(t.employeeNo)}</strong><small>${esc(ocrStateLabel(t))} · 已尝试 ${t.attemptCount} 次</small></div>${button('查看进度','ocr-progress',`data-job="${t.jobId}"`,'soft')}</section>`).join('')||'<div class="empty">当前没有匹配的识别任务</div>'}<div class="actions"><span>共 ${data.total} 条 · 第 ${page} 页</span>${button('上一页','ocr-tasks',`data-ocr-state="${state}" data-ocr-page="${page-1}" ${page<=1?'disabled':''}`,'soft')}${button('下一页','ocr-tasks',`data-ocr-state="${state}" data-ocr-page="${page+1}" ${page*10>=data.total?'disabled':''}`,'soft')}</div>`);}
async function showOcrTask(id){const t=await api('/ocr/tasks/'+id),active=['queued','running','retry_wait'].includes(t.state);if(t.state==='succeeded')await refresh();const steps=['原始文件保存','识别任务处理','PDF解析与文字识别','档案字段提取','医学项目匹配','结果校验与保存'];const stage=['queued','pdf_parse','ocr','field_extraction','item_matching','validation','finished'].indexOf(t.stage);let complete=t.state==='succeeded'?6:t.state==='running'?Math.max(2,stage>=3?stage:2):1;
modal('报告识别进度',`<section id="ocr-progress"><div class="ocr-status ${t.state}"><span class="ocr-status-dot"></span><div><h3>${esc(ocrStateLabel(t))}</h3><p>${esc(active? t.state==='running'?ocrStageNames[t.stage]:'原件已保存，识别服务在线后将自动处理。':'succeeded'===t.state?'识别结果已保存为候选，请核对原件后提交医生审核。':t.errorMessage||'原始文件与处理记录仍然保留。')}</p></div><b>${Number(t.percent||0)}%</b></div><div class="ocr-track"><i style="width:${Number(t.percent||0)}%"></i></div><ol class="ocr-steps">${steps.map((label,i)=>`<li class="${i<complete?'done':i===complete?'current':''}"><span>${i<complete?'✓':i+1}</span>${label}</li>`).join('')}</ol><p class="notice">已处理 ${t.attemptCount} 次 · 文件保留。识别完成不会自动审核或归档。</p>${t.errorCode?`<p class="ocr-warning">${esc(t.errorCode)}：${esc(t.errorMessage||'请重试或联系管理员')}</p>`:''}<div class="actions">${t.state==='failed'?button('重新排队重试','ocr-control',`data-job="${id}" data-control="retry"`):''}${active?button('停止识别','ocr-control',`data-job="${id}" data-control="cancel"`,'soft'):''}${button('核对报告结果','candidate',`data-report="${t.reportId}" data-rev="${t.revision}"`,'light')}${button('全部识别任务','ocr-tasks','','soft')}</div>${t.attempts.length?`<details><summary>查看处理记录（${t.attempts.length}次）</summary>${t.attempts.map(a=>`<p>第${a.attemptNumber}次 · ${{running:'处理中',succeeded:'已完成',failed:'失败',expired:'心跳超时',cancelled:'已停止'}[a.outcome]||esc(a.outcome)} · ${esc(a.startedAt)} ${a.errorMessage?' · '+esc(a.errorMessage):''}</p>`).join('')}</details>`:''}</section>`);dialog.dataset.ocrJob=id;if(active)ocrTimer=setTimeout(async()=>{if(dialog.open&&dialog.dataset.ocrJob===id){try{await showOcrTask(id)}catch(e){toast(e.message)}}},2000);else await refresh();}
async function controlOcr(id,control){modal(control==='retry'?'重新发起识别':'停止识别任务',`<form id="ocr-control-form"><p>原始报告文件和既有审核记录会继续保留。</p><label>操作说明<textarea name="note" required maxlength="600"></textarea></label><button class="btn">确认${control==='retry'?'重试':'停止'}</button></form>`);formHandler('ocr-control-form',async f=>{await api('/ocr/tasks/'+id+'/'+control,'POST',{note:f.elements.note.value,requestKey:uid()});await showOcrTask(id)});}
function uploadRequest(url,data,key,progress){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST',url);xhr.withCredentials=true;xhr.timeout=120000;xhr.setRequestHeader('X-CSRF-Token',ctx.csrfToken);xhr.setRequestHeader('Idempotency-Key',key);xhr.upload.onprogress=e=>{if(e.lengthComputable)progress(Math.round(e.loaded/e.total*100))};xhr.onload=()=>{try{const j=JSON.parse(xhr.responseText);if(xhr.status<200||xhr.status>=300||j.code!==0)reject(Error(j.msg||'上传失败'));else resolve(j.data)}catch(e){reject(Error('上传未返回有效结果，请检查网络后重试'))}};xhr.onerror=()=>reject(Error('网络连接失败，请重试上传'));xhr.ontimeout=()=>reject(Error('上传超时，请检查网络后重试'));xhr.send(data)});}
async function upload(camera=false){let selected=person?.id||list.items[0]?.id,options=list.items.slice();if(!selected){modal('上传报告','<p>请先新增或选择职工档案。</p>'+button('新增档案','new'));return}let uploadKey=uid();modal('上传原始体检报告',`<form id="upload-form"><p>支持多页PDF、JPG/JPEG、PNG，单份≤20 MB。原件保存后自动加入识别队列，最多同时识别 ${Number(ctx.recognition?.concurrentReports||1)} 份，其余自动排队；报告中的姓名、性别和年龄仅保存到报告候选，不自动修改职工资料。</p>${ctx.recognition?.provider==='model'?'<p class="ocr-warning">当前使用模型识别。原件页面将发送至模型服务，识别结果需人工核对后归档。</p>':''}<div class="ocr-upload-person"><input id="upload-search" placeholder="搜索职工：姓名或工号"><label>所属职工<select name="record">${options.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)} · ${esc(p.code)}</option>`).join('')}${person&&!options.some(x=>x.id===person.id)?`<option value="${person.id}" selected>${esc(person.name)} · ${esc(person.code)}</option>`:''}</select></label></div><label class="upload-zone ocr-drop-zone" id="ocr-drop-zone"><span class="ocr-upload-symbol">↑</span><strong>拖拽文件到这里，或点击选择文件</strong><small>保留原始PDF / 照片，识别结果需人工核对</small><input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg,application/pdf,image/png,image/jpeg" ${camera?'capture="environment"':''} required><span id="selected-file">尚未选择文件</span></label><progress id="upload-progress" value="0" max="100" hidden></progress><p id="upload-status" aria-live="polite"></p><button class="btn">上传并开始处理</button></form>`);let timer;document.getElementById('upload-search').oninput=e=>{clearTimeout(timer);timer=setTimeout(async()=>{try{let data=await api('/records?limit=50&search='+encodeURIComponent(e.target.value));document.querySelector('#upload-form select').innerHTML=data.items.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.code)}</option>`).join('')}catch(e){toast(e.message)}},350)};const zone=document.getElementById('ocr-drop-zone'),input=document.querySelector('#upload-form input[type=file]');input.onchange=()=>{uploadKey=uid();const f=input.files[0];document.getElementById('selected-file').textContent=f?f.name+' · '+(f.size/1024/1024).toFixed(2)+' MB':'尚未选择文件'};zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragover')};zone.ondragleave=()=>zone.classList.remove('dragover');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragover');if(e.dataTransfer.files.length!==1){toast('请每次选择一份报告，完整PDF可包含多页');return}input.files=e.dataTransfer.files;input.onchange()};formHandler('upload-form',async f=>{const file=f.elements.file.files[0];if(!file)throw Error('请选择报告文件');if(file.size>20971520)throw Error('文件超过20 MB');let b=new FormData();b.append('file',file);b.append('channel',camera?'phone_photo':'backend_file');const progress=document.getElementById('upload-progress'),status=document.getElementById('upload-status');progress.hidden=false;status.textContent='正在上传原件…';const r=await uploadRequest('/ehr/api/records/'+f.elements.record.value+'/reports',b,uploadKey,p=>{progress.value=p;status.textContent=p===100?'原件已发送，正在保存与创建任务…':'正在上传原件 '+p+'%'});await refresh();if(r.ocrTask)await showOcrTask(r.ocrTask.jobId);else{dialog.close();toast('原件已保存，报告记录已更新')}});}

function valueOf(r,key){return r.fieldValues.find(x=>x.field_key===key)?.value_raw||'';}
function normalizeExamDate(raw){
 const s=String(raw??'').trim().replace(/^体检(?:日期|时间)\s*[：:]\s*/,'').replace(/[/.]/g,'-');
 const m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/)||s.match(/^(\d{4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日$/);
 if(!m)return '';
 const y=Number(m[1]),month=Number(m[2]),day=Number(m[3]);
 if(y<1000||y>9999||month<1||month>12||day<1)return '';
 const maxDay=new Date(Date.UTC(y,month,0)).getUTCDate();
 return day<=maxDay?`${m[1]}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`:'';
}
function draftExamDate(r){
 if(r.examDate)return normalizeExamDate(r.examDate);
 const evidence=r.fieldEvidence||[];
 const anchored=[...new Set((r.fieldValues||[]).filter(f=>f.field_key==='exam_date').flatMap(f=>evidence.filter(e=>(f.evidence_ids||[]).includes(e.id)).flatMap(e=>[...String(e.quote||'').matchAll(/(?<!下次)(?<!预约)(?<!建议)体检(?:日期|时间)\s*[：:]\s*(\d{4}\s*[-/.年]\s*\d{1,2}\s*[-/.月]\s*\d{1,2}\s*日?)/g)].map(m=>normalizeExamDate(m[1])))).filter(Boolean))];
 if(anchored.length)return anchored.length===1?anchored[0]:'';
 const primary=normalizeExamDate(r.examDateRaw);
 if(primary)return primary;
 // Never substitute a departmental check_date or a report issue date.
 const values=[...new Set((r.fieldValues||[]).filter(f=>f.field_key==='exam_date'&&!/总检|检查|打印|签发|下次|预约|复查|建议/.test(f.original_field_name||'')).map(f=>normalizeExamDate(f.value_raw)).filter(Boolean))];
 return values.length===1?values[0]:'';
}
function draftInstitution(r){
 if(r.institution)return r.institution;
 const fields=(r.fieldValues||[]).filter(f=>f.field_key==='institution'&&f.value_raw);
 const cover=fields.filter(f=>(r.fieldEvidence||[]).some(e=>(f.evidence_ids||[]).includes(e.id)&&Number(e.page)===1));
 const values=[...new Set((cover.length?cover:fields).map(f=>f.value_raw))];
 return values.length===1?values[0]:'';
}
function formalConclusions(r){
 return (r.conclusions||[]).filter(c=>!/(?:异常结果汇总|分科|小结|检查意见|诊断意见|影像诊断)/.test(c.label||'')).filter(c=>/[\p{L}\p{N}]/u.test(c.text||''));
}
function metricRow(i={}){return `<tr data-item-code="${esc(i.itemCode||'')}">${[['name','项目名称'],['value','结果原文'],['unit','单位原文'],['referenceRange','参考范围'],['abnormal','异常标记'],['page','页码']].map(([k,n])=>`<td><input data-item="${k}" aria-label="${n}" value="${esc(i[k]??(k==='page'?1:''))}" ${k==='page'?'type="number" min="1"':''}></td>`).join('')}<td><button type="button" data-do="remove-item">移除</button></td></tr>`;}
async function candidate(id,rev){editor=await api('/reports/'+id+'/'+rev);const r=editor;modal('按原件补录 / 核对报告 · V'+rev,`<form id="candidate-form">${r.requiresReportKindConfirmation?'<p class="ocr-warning">OCR暂未确定报告类型：当前仅保存候选。医生审核时须确认这是该职工个人体检报告；若为机构汇总或多人报告，请退回处理。</p>':''}<p>结果、单位和参考范围按原文填写，支持复合值与定性结果；不会自动换算单位。</p>${!r.examDate?'<p class="ocr-warning">'+(draftExamDate(r)?'已回填识别到的候选体检日期，请对照原件核对后保存；当前尚未核定或归档。':r.examDateRaw?'识别日期原文：'+esc(r.examDateRaw)+'。请核对并选择体检日期。':'尚未识别到报告级体检日期，请对照原件填写。')+'</p>':''}<div class="form-fields">${field('fullName','报告受检者姓名 *',valueOf(r,'full_name'),'text',true)}${field('examDate','核定体检日期 *',draftExamDate(r),'date',true)}${field('institution','体检机构',draftInstitution(r))}${field('metadataPage','姓名 / 日期 / 机构所在页',1,'number')}${field('conclusionPage','完整结论所在页',formalConclusions(r)[0]?.page||1,'number')}<label class="wide">完整体检结论（原文）<textarea name="formalConclusion" rows="3" maxlength="12000">${esc(formalConclusions(r).map(c=>c.text||'').join('\n'))}</textarea></label><label class="wide">医师建议（报告原文）<textarea name="advice" rows="2" maxlength="12000">${esc(r.advice.map(c=>c.text||'').join('\n'))}</textarea></label></div><div class="table-scroll"><table class="metrics-editor"><thead><tr><th>项目名</th><th>结果原文</th><th>单位</th><th>参考范围</th><th>标记</th><th>页码</th><th></th></tr></thead><tbody id="metric-rows">${(r.items.length?r.items:[{}]).map(metricRow).join('')}</tbody></table></div>${button('＋ 添加检查项目','add-item','','soft')}<button class="btn">保存候选结果</button></form>`);formHandler('candidate-form',async f=>{let b=Object.fromEntries(new FormData(f));b.items=Array.from(document.querySelectorAll('#metric-rows tr')).map(tr=>Object.assign(Object.fromEntries(Array.from(tr.querySelectorAll('[data-item]')).map(i=>[i.dataset.item,i.value])),{itemCode:tr.dataset.itemCode||''})).filter(i=>Object.entries(i).some(([k,v])=>k!=='page'&&v));await api('/reports/'+id+'/'+rev,'PUT',b,{'If-Match':r.etag});dialog.close();await refresh();toast('候选结果已保存，需提交医生审核')});}
async function action(id,rev,action){const reviewed=await api('/reports/'+id+'/'+rev);const label={submit:'提交人工审核',approve:'医生确认',archive:'正式归档',return:'退回补充',reject:'驳回报告'}[action];modal(label,`<form id="action-form"><p>${action==='approve'?'请逐项核对原件、完整结论及异常结果；确认后本版本不可覆盖。':action==='archive'?'正式发布此版本，保留原件、医生确认快照和归档记录。':'此操作将保存业务处理记录。'}</p><label>处理说明<textarea name="note" rows="3" maxlength="600" ${action!=='submit'?'required':''}></textarea></label>${action==='approve'?'<label class="check"><input name="identity" type="checkbox" required>已依据授权资料核验受检者身份，并逐项核对原件与候选结果</label>':''}${action==='approve'&&reviewed.requiresReportKindConfirmation?'<label class="check"><input name="reportKind" type="checkbox" required>已核对原件，确认这是该职工个人体检报告，非机构汇总或多人报告</label>':''}<button class="btn">确认${label}</button></form>`);formHandler('action-form',async f=>{await api('/reports/'+id+'/'+rev+'/actions','POST',{action,etag:reviewed.etag,note:f.note.value,identityVerified:!!f.identity?.checked,reportKindVerified:!!f.reportKind?.checked,requestKey:uid()});dialog.close();await refresh();toast('操作完成，数据库已留痕')});}
async function revise(id,rev){modal('建立修订版本',`<form id="revise-form"><p>原版本及其审核记录保留，新版本复制原始数据供更正。</p><textarea name="note" placeholder="修订原因" required maxlength="600"></textarea><button class="btn">建立下一版本</button></form>`);formHandler('revise-form',async f=>{await api('/reports/'+id+'/'+rev+'/revisions','POST',{note:f.note.value});dialog.close();await refresh()});}
async function removeReport(id,rev){
 const r=await api('/reports/'+id+'/'+rev);
 if(!r.canRemove)throw Error('这份报告已有审核记录或版本变化，不能移除。');
 const requestKey=uid();
 modal('移除这份体检报告',`<form id="remove-report-form"><div class="remove-report-notice"><strong>${esc(r.files[0]?.name||'体检报告')} · V${rev}</strong><p>确认后，此报告将从职工档案中移除，进行中的识别任务会停止。职工资料和其他报告不受影响，原件与处理记录保留备查。</p></div><label>移除原因<textarea name="reason" required maxlength="600" placeholder="例如：选错职工、上传了他人的报告"></textarea></label><div class="actions"><button type="button" class="btn soft" data-do="close">取消</button><button type="submit" class="btn danger-fill">确认移除</button></div></form>`);
 formHandler('remove-report-form',async f=>{
  await api('/reports/'+id+'/'+rev,'DELETE',{reason:f.reason.value,requestKey},{'If-Match':r.etag});
  dialog.close();await refresh();toast('报告已移除，可以重新上传。');
 });
}

async function history(id,rev){const r=await api('/reports/'+id+'/'+rev);modal('报告详情与历史版本',`<p>报告ID：${esc(id)} · V${rev}</p><div class="actions">${r.versions.map(v=>button('V'+v.revision+' · '+(v.reviewStatus),'history',`data-report="${id}" data-rev="${v.revision}"`,'soft')).join('')}</div><h3>报告原始字段</h3><div class="table-scroll"><table><tbody>${r.fieldValues.map(v=>`<tr><td>${esc(v.original_field_name)}</td><td>${esc(v.value_raw??'未识别')}</td><td>${esc(v.review_status)}</td></tr>`).join('')}</tbody></table></div><h3>审核记录</h3>${r.reviews.map(v=>`<p>${esc(v.time)} · ${esc(v.reviewer)} · ${esc(v.decision)}</p>`).join('')||'<p>尚未审核</p>'}<div class="actions">${r.files.map(f=>`<a class="btn soft" href="/ehr/api/files/${f.id}">下载${esc(f.name)}</a>`).join('')}</div>`);}
function parseCSV(s){const rows=[];let row=[],cell='',quote=false;s=s.replace(/^\ufeff/,'');for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(quote&&s[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&s[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}if(quote)throw Error('CSV引号未闭合');row.push(cell);if(row.some(Boolean))rows.push(row);return rows;}
function importer(){modal('批量导入授权职工档案',`<form id="import-form"><p>UTF-8 CSV，首行为：姓名,工号,手机号,性别,单位,班组,岗位。单批1–500条；任一条失败则整批回滚。</p><input name="file" type="file" accept=".csv,text/csv" required><button class="btn">校验并导入</button></form>`);formHandler('import-form',async f=>{if(f.file.files[0].size>2097152)throw Error('CSV请小于2 MB');let rows=parseCSV(await f.file.files[0].text()),head=rows.shift(),keys={姓名:'name',工号:'code',手机号:'phone',性别:'sex',单位:'org',班组:'team',岗位:'job'};if(!head.includes('姓名')||!head.includes('工号'))throw Error('必须包含姓名和工号列');let body=rows.map(r=>{let p={sex:'未填写'};head.forEach((h,i)=>{if(keys[h])p[keys[h]]=r[i]||''});return p});let data=await api('/records/import','POST',body);dialog.close();await refresh();toast('已导入'+data.imported+'条档案')});}
async function guard(fn){try{await fn()}catch(e){toast(e.message)}}
document.addEventListener('change',e=>{if(e.target.dataset.check){e.target.checked?chosen.add(e.target.dataset.check):chosen.delete(e.target.dataset.check)}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.person){guard(async()=>{person=await api('/records/'+b.dataset.person);drawArchive()});return}if(b.dataset.status){filters={status:b.dataset.status==='all'?'':b.dataset.status};list.page=1;chosen.clear();guard(refresh);return}if(b.dataset.filter){filters={};if(b.dataset.filter==='high')filters.risk='high';else if(b.dataset.filter!=='total')filters.status=b.dataset.filter;list.page=1;guard(refresh);return}const a=b.dataset.do;if(!a)return;guard(async()=>{if(a==='close'){clearTimeout(ocrTimer);delete dialog.dataset.ocrJob;dialog.close();}if(a==='refresh')await refresh();if(a==='new')await edit();if(a==='binding-code')await bindingSettings(b.dataset.id);if(a==='corrections')await corrections(b.dataset.id||'',b.dataset.statusCorrection||'pending',Number(b.dataset.correctionPage||1));if(a==='revoke-binding-code'){await api('/records/'+b.dataset.id+'/binding-code','DELETE');dialog.close();toast('验证码已撤销')}if(a==='edit')await edit(b.dataset.id);if(a==='upload'||a==='camera')await upload(a==='camera');if(a==='page')await changeListPage(Number(b.dataset.page));if(a==='reset'){filters={};list.page=1;await refresh()}if(a==='candidate')await candidate(b.dataset.report,Number(b.dataset.rev));if(a==='action')await action(b.dataset.report,Number(b.dataset.rev),b.dataset.action);if(a==='ocr'){const t=await api('/reports/'+b.dataset.report+'/'+b.dataset.rev+'/ocr','POST');await refresh();await showOcrTask(t.jobId)}if(a==='ocr-tasks')await ocrTaskList(b.dataset.ocrState||'active',Number(b.dataset.ocrPage||1));if(a==='ocr-progress')await showOcrTask(b.dataset.job);if(a==='ocr-control')await controlOcr(b.dataset.job,b.dataset.control);if(a==='history')await history(b.dataset.report,Number(b.dataset.rev));if(a==='remove-report')await removeReport(b.dataset.report,Number(b.dataset.rev));if(a==='revise')await revise(b.dataset.report,Number(b.dataset.rev));if(a==='add-item'){e.preventDefault();document.getElementById('metric-rows').insertAdjacentHTML('beforeend',metricRow())}if(a==='remove-item'){e.preventDefault();b.closest('tr').remove()}if(a==='import')importer();if(a==='sync'){await refresh();let count=stats.sources.find(x=>x.channel==='miniapp')?.count||0;modal('小程序上传已接入',`<p>当前单位已接收 ${count} 次小程序上传。后台和小程序使用同一档案与报告库，无需复制同步。</p><p>小程序通过微信登录、验证职工身份并确认后台资料后获取本人档案权限。上传接口：<code>POST /ehr/miniapp/reports</code>；未绑定用户不能上传。</p>`)}if(a==='delete'){const p=await api('/records/'+b.dataset.id);modal('删除档案 · '+p.name,`<form id="delete-form"><p>删除此职工档案时，将同时删除其所有体检报告、识别结果、审核数据及上传原件（含已审核版本）。此操作不可恢复，请核对后确认。</p><textarea name="reason" required placeholder="删除原因" maxlength="600"></textarea><button class="btn">确认删除</button></form>`);formHandler('delete-form',async f=>{await api('/records/'+p.id,'DELETE',{reason:f.reason.value,rowVersion:p.rowVersion});chosen.delete(p.id);dialog.close();await refresh()})}if(a==='batch-approve'||a==='batch-archive'){if(!chosen.size)throw Error('请先选择档案');let details=await Promise.all(Array.from(chosen).map(id=>api('/records/'+id))),reports=details.flatMap(p=>p.reports.filter(r=>a==='batch-approve'?r.stage==='pending_review':r.reviewStatus==='confirmed'&&!r.published));if(!reports.length)throw Error('没有符合当前处理状态的报告');modal('批量'+(a==='batch-approve'?'审核':'归档'),`<form id="batch-form"><p>共${reports.length}份报告，整批按事务提交。请先逐份查看原件。</p><textarea name="note" placeholder="处理说明" required maxlength="600"></textarea><label class="check"><input name="identity" type="checkbox" required>已逐份核对原件、身份及检查结果</label>${a==='batch-approve'&&reports.some(r=>r.requiresReportKindConfirmation)?'<label class="check"><input name="reportKind" type="checkbox" required>已逐份核对类型不确定的原件，确认均为对应职工个人报告，非机构汇总或多人报告</label>':''}<button class="btn">确认处理</button></form>`);formHandler('batch-form',async f=>{await api('/reports/batch-actions','POST',reports.map(r=>({reportId:r.id,revision:r.revision,etag:r.etag,action:a==='batch-approve'?'approve':'archive',note:f.note.value,identityVerified:f.identity.checked,reportKindVerified:!!f.reportKind?.checked,requestKey:uid()})));dialog.close();chosen.clear();await refresh()})}})});
dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});window.addEventListener('resize',()=>charts.forEach(c=>c.resize()));
(async()=>{try{ctx=await api('/context');try{ctx.recognition=await api('/recognition')}catch(ignore){}if(isListView)readListLocation();await refresh();restoreListPosition();
if(view==='management'&&new URLSearchParams(location.search).get('action')==='upload')await guard(upload);
}catch(e){app.innerHTML=`<main class="shell"><section class="panel empty"><h2>暂时无法加载健康档案</h2><p>${esc(e.message)}</p><button class="btn" onclick="location.reload()">重新加载</button> <a href="/login" target="_top">重新登录</a></section></main>`}})();
})();
